style.css:
@-moz-document domain("meet.google.com") {
/* 1. Main Background & Controls Bar */
    .a4bet, .cr47fe, .UnvNgf, .t424Sc {
        background-color: #ffeef2 !important; /* Soft Pastel Pink */
    }
    
    /* 2. Bottom Control Bar Panels */
    .Gv7Sgc, .J01ur, .pH4xbe {
        background: rgba(255, 194, 209, 0.9) !important; /* Semi-transparent baby pink */
        border-radius: 20px !important;
        border: 2px dashed #ffb3c6 !important;
    }

    /* 3. Text and Video Grid Customization */
    .Z43M7, .yg11tc, .G47vbd {
        color: #ff758f !important; /* Deep berry pink text */
        font-family: "Comic Sans MS", "Chalkboard SE", cursive, sans-serif !important;
    }

    /* 4. Action Buttons (Mute, Camera, End Call) */
    .V639qd, .U26qgb, .FTuzee {
        background-color: #ffccd5 !important;
        border: 2px solid #ff85a1 !important;
        color: #ff477e !important;
    }
    
    /* Hover effect for buttons */
    .V639qd:hover, .U26qgb:hover {
        background-color: #ffb3c6 !important;
        transform: scale(1.05);
        transition: all 0.2s ease-in-out;
    }

    /* 5. The Leave Call Button (Make it a cute red/pink accent) */
    .FTuzee {
        background-color: #ff477e !important;
        color: #ffffff !important;
    }

    /* 6. Chat and People Sidebar Panel */
    .R32ccb, .Q8rAEc, .XthBdf {
        background-color: #ffffff !important;
        border-left: 3px dotted #ffccd5 !important;
    }
    
    /* Chat bubbles */
    .gdma8e {
        background-color: #fff0f3 !important;
        border-radius: 12px !important;
        color: #ff758f !important;
    }
}
